-- 001_identity: cloud identity foundation.
--
-- Passwords never exist. A user signs in with a six-digit code mailed to
-- their address; the code is stored only as an HMAC digest. Sessions are
-- random tokens whose SHA/HMAC digest is stored here. All ids are UUIDs
-- generated by the application, and every timestamp is timestamptz so a
-- deployment can move between zones without reinterpreting history.

CREATE TABLE users (
    id                uuid        PRIMARY KEY,
    email             text        NOT NULL,
    email_normalized  text        NOT NULL,
    role              text        NOT NULL DEFAULT 'user',
    status            text        NOT NULL DEFAULT 'active',
    auth_version      integer     NOT NULL DEFAULT 1,
    email_verified_at timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now(),
    updated_at        timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT users_email_normalized_key UNIQUE (email_normalized),
    CONSTRAINT users_email_shape CHECK (
        length(btrim(email)) BETWEEN 3 AND 254
        AND position('@' in email) > 1
        AND position('@' in email) < length(email)
    ),
    CONSTRAINT users_email_normalized_canonical CHECK (
        email_normalized = lower(btrim(email_normalized))
        AND length(email_normalized) BETWEEN 3 AND 254
        AND position('@' in email_normalized) > 1
        AND position('@' in email_normalized) < length(email_normalized)
    ),
    CONSTRAINT users_role_valid CHECK (role IN ('user', 'admin')),
    CONSTRAINT users_status_valid CHECK (status IN ('active', 'disabled')),
    CONSTRAINT users_auth_version_positive CHECK (auth_version > 0)
);

CREATE TABLE email_codes (
    id               uuid        PRIMARY KEY,
    email_normalized text        NOT NULL,
    purpose          text        NOT NULL,
    code_hash        bytea       NOT NULL,
    hash_version     smallint    NOT NULL DEFAULT 1,
    attempts         smallint    NOT NULL DEFAULT 0,
    max_attempts     smallint    NOT NULL DEFAULT 5,
    created_at       timestamptz NOT NULL DEFAULT now(),
    expires_at       timestamptz NOT NULL,
    consumed_at      timestamptz,
    request_ip       inet,

    CONSTRAINT email_codes_email_shape CHECK (
        email_normalized = lower(btrim(email_normalized))
        AND length(email_normalized) BETWEEN 3 AND 254
        AND position('@' in email_normalized) > 1
        AND position('@' in email_normalized) < length(email_normalized)
    ),
    CONSTRAINT email_codes_purpose_valid CHECK (purpose ~ '^[a-z][a-z0-9_]{2,31}$'),
    CONSTRAINT email_codes_hash_length CHECK (octet_length(code_hash) = 32),
    CONSTRAINT email_codes_hash_version_positive CHECK (hash_version > 0),
    CONSTRAINT email_codes_attempts_valid CHECK (
        attempts >= 0 AND max_attempts > 0 AND attempts <= max_attempts
    ),
    CONSTRAINT email_codes_expiry_after_creation CHECK (expires_at > created_at)
);

-- At most one code can be used for an email and purpose. Issuing a new one
-- marks the previous one consumed in the same transaction.
CREATE UNIQUE INDEX email_codes_one_live
    ON email_codes (email_normalized, purpose)
    WHERE consumed_at IS NULL AND attempts < max_attempts;

-- Send throttling and the latest-code lookup.
CREATE INDEX email_codes_email_created
    ON email_codes (email_normalized, created_at DESC);
CREATE INDEX email_codes_ip_created
    ON email_codes (request_ip, created_at DESC)
    WHERE request_ip IS NOT NULL;
CREATE INDEX email_codes_expiry
    ON email_codes (expires_at)
    WHERE consumed_at IS NULL;

CREATE TABLE user_sessions (
    id           uuid        PRIMARY KEY,
    user_id      uuid        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash   bytea       NOT NULL,
    auth_version integer     NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    revoked_at   timestamptz,
    user_agent   text,
    request_ip   inet,

    CONSTRAINT user_sessions_token_hash_key UNIQUE (token_hash),
    CONSTRAINT user_sessions_hash_length CHECK (octet_length(token_hash) = 32),
    CONSTRAINT user_sessions_auth_version_positive CHECK (auth_version > 0),
    CONSTRAINT user_sessions_expiry_after_creation CHECK (expires_at > created_at)
);

CREATE INDEX user_sessions_user_live
    ON user_sessions (user_id)
    WHERE revoked_at IS NULL;
CREATE INDEX user_sessions_expiry
    ON user_sessions (expires_at)
    WHERE revoked_at IS NULL;
